INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM206J0JN', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = 5 \\cdot 3^x$. The function $g$ is defined by $g(x) = f(x + 2)$. Which of the following expressions is equal to $g(x)$ and is written in the form $c \\cdot 3^x$, where $c$ is a constant?', NULL, $lyceon_json$[{"key":"A","text":"$45 \\cdot 3^x$"},{"key":"B","text":"$15 \\cdot 3^x$"},{"key":"C","text":"$10 \\cdot 3^x$"},{"key":"D","text":"$30 \\cdot 3^x$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting: $g(x) = f(x + 2) = 5 \\cdot 3^{x+2} = 5 \\cdot 3^x \\cdot 3^2 = 5 \\cdot 9 \\cdot 3^x = 45 \\cdot 3^x$. The expression $15 \\cdot 3^x$ results from computing $5 \\cdot 3 = 15$ instead of $5 \\cdot 3^2 = 45$, using $3^1$ instead of $3^2$. The expression $10 \\cdot 3^x$ results from multiplying $5 \\cdot 2$, treating the horizontal shift of $2$ as a multiplicative factor on the coefficient. The expression $30 \\cdot 3^x$ results from computing $5 \\cdot 6 = 30$, likely from $5 \\cdot (3 \\cdot 2)$ by incorrectly mixing the shift value and the base.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21KSUL8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two angles are supplementary. One angle measures $137°$. What is the measure, in degrees, of the other angle?', NULL, $lyceon_json$[{"key":"A","text":"$43$"},{"key":"B","text":"$47$"},{"key":"C","text":"$53$"},{"key":"D","text":"$137$"}]$lyceon_json$::jsonb, 'A', NULL, E'Supplementary angles sum to $180°$. The other angle is $180 - 137 = 43°$. The distractor $47$ results from a subtraction error when computing $180 - 137$ (for example, computing $80 - 37 = 43$ but then writing $47$). The distractor $53$ arises from an arithmetic slip such as computing $190 - 137 = 53$. The distractor $137$ reflects the misconception that supplementary angles are equal rather than summing to $180°$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
