INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23KWKTD', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution of $x^2 + 3x - 28 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Factor $x^2 + 3x - 28 = 0$ by finding two numbers that multiply to $-28$ and add to $3$. Those numbers are $7$ and $-4$, giving $(x + 7)(x - 4) = 0$. The solutions are $x = -7$ and $x = 4$. The positive solution is $x = 4$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23ZLYXX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A retailer marks up a wholesale item by $40\\%$ and then offers a $25\\%$ discount on the marked-up price. If the wholesale price of the item is $\\$70$, what is the final sale price?', NULL, $lyceon_json$[{"key":"A","text":"$\\$52.50$"},{"key":"B","text":"$\\$73.50$"},{"key":"C","text":"$\\$80.50$"},{"key":"D","text":"$\\$91.00$"}]$lyceon_json$::jsonb, 'B', NULL, E'The marked-up price is $70 \\times 1.40 = \\$98$. Applying the $25\\%$ discount: $98 \\times 0.75 = \\$73.50$. The value $\\$52.50$ results from applying only the $25\\%$ discount to the wholesale price without the markup: $70 \\times 0.75 = 52.50$, ignoring the first step entirely. The value $\\$80.50$ results from netting the two percentages as $40\\% - 25\\% = 15\\%$ and computing $70 \\times 1.15 = 80.50$, which incorrectly treats successive percentage changes as additive. The value $\\$91.00$ results from applying the discount only to the markup amount: $70 \\times 0.40 = 28$, then $28 \\times 0.75 = 21$, then $70 + 21 = 91$, rather than applying the discount to the full marked-up price.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25X3AUN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $JKL$, the exterior angle at vertex $K$ measures $127°$. If angle $J$ is $13°$ more than angle $L$, what is the measure, in degrees, of angle $L$?', NULL, $lyceon_json$[{"key":"A","text":"$53$"},{"key":"B","text":"$57$"},{"key":"C","text":"$63.5$"},{"key":"D","text":"$70$"}]$lyceon_json$::jsonb, 'B', NULL, E'An exterior angle of a triangle equals the sum of the two non-adjacent interior angles. So angle $J$ + angle $L$ = $127°$. Since angle $J = L + 13$, substituting gives $(L + 13) + L = 127$, which simplifies to $2L = 114$ and $L = 57$. The distractor $53$ comes from computing the interior angle at $K$ as $180 - 127 = 53$ and reporting that instead. The distractor $63.5$ arises from ignoring the $13°$ difference and dividing $127 / 2 = 63.5$. The distractor $70$ results from solving for angle $J = 57 + 13 = 70$ instead of angle $L$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM268CT87', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A function is defined by $f(x) = -3x + 17$. What is the value of $f(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$5$"},{"key":"C","text":"$29$"},{"key":"D","text":"$68$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 4$: $f(4) = -3(4) + 17 = -12 + 17 = 5$. The value $-5$ results from dropping the negative sign on the coefficient and computing $3(4) - 17 = 12 - 17 = -5$. The value $29$ results from misreading the function as $f(x) = 3x + 17$ and computing $3(4) + 17 = 29$. The value $68$ results from multiplying only $17 \\times 4 = 68$, ignoring the $-3x$ term entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26X8W2L', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'What are all values of $x$ that satisfy $-5x + 14 \\geq 39$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\leq -5$"},{"key":"B","text":"$x \\geq -5$"},{"key":"C","text":"$x \\leq 5$"},{"key":"D","text":"$x \\geq 5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Starting with $-5x + 14 \\geq 39$, subtract $14$ from both sides: $-5x \\geq 25$. Divide both sides by $-5$, which reverses the inequality direction: $x \\leq -5$. The answer $x \\geq -5$ results from forgetting to flip the inequality sign when dividing by a negative number. The answer $x \\leq 5$ comes from dropping the negative sign on the result. The answer $x \\geq 5$ combines both errors: failing to flip and losing the negative.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28CPAKD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A data set consists of $11$ values whose mean is $37$. The smallest value in the data set is $13$, and it is removed. What is the mean of the remaining $10$ values?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '39.4', ARRAY['197/5', '39.4'], E'The sum of all 11 values is $11 \\times 37 = 407$. After removing the value $13$, the sum of the remaining 10 values is $407 - 13 = 394$. The new mean is $\\frac{394}{10} = 39.4$. A common error is dividing by $11$ instead of $10$ after removal, giving $\\frac{394}{11} \\approx 35.8$. Another error is subtracting $13$ from the mean directly, giving $37 - 13 = 24$, rather than working with the total sum.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28V6MKT', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'Which of the following equations represents the line passing through the points $(1, 7)$ and $(4, -2)$?', NULL, $lyceon_json$[{"key":"A","text":"$y = -3x + 4$"},{"key":"B","text":"$y = -3x + 7$"},{"key":"C","text":"$y = -3x + 10$"},{"key":"D","text":"$y = 3x + 4$"}]$lyceon_json$::jsonb, 'C', NULL, E'The slope is $\\frac{-2 - 7}{4 - 1} = \\frac{-9}{3} = -3$. Using point-slope form with $(1, 7)$: $y - 7 = -3(x - 1)$, which gives $y = -3x + 3 + 7 = -3x + 10$. The equation $y = -3x + 4$ results from incorrectly writing $y - 7 = -3(x + 1)$ instead of $-3(x - 1)$, yielding $y = -3x - 3 + 7 = -3x + 4$. The equation $y = -3x + 7$ results from assuming the $y$-coordinate of the first point is the $y$-intercept. The equation $y = 3x + 4$ results from computing the slope as $\\frac{7 - (-2)}{4 - 1} = \\frac{9}{3} = 3$ (omitting the sign), then using $y - 7 = 3(x - 1)$ to get $y = 3x + 4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28V9SA7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle with center $(h, k)$ passes through the points $(3, 5)$ and $(73, 5)$. The radius of the circle is $37$. If $k > 5$, what is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'The chord connecting $(3, 5)$ and $(73, 5)$ has length $73 - 3 = 70$. Its midpoint is $(38, 5)$, and the perpendicular bisector of this horizontal chord is the vertical line $x = 38$, so $h = 38$. The half-chord length is $35$. Using the Pythagorean theorem with the radius: the distance from the center to the chord satisfies $d^2 + 35^2 = 37^2$, giving $d^2 = 1369 - 1225 = 144$ and $d = 12$. Since $k > 5$, the center is above the chord, so $k = 5 + 12 = 17$. A common error is computing $d = 12$ but forgetting to add the chord''s $y$-coordinate, giving $12$ instead of $17$. Another error is using the full chord length $70$ instead of the half-chord $35$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29BXYOB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'The equation $y = -3.2x + 89$ models the relationship between the number of hours of television watched per week, $x$, and a student''s exam score, $y$. Which of the following is the best interpretation of the slope of this equation?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of television watched per week, the predicted exam score decreases by $3.2$ points."},{"key":"B","text":"For each additional hour of television watched per week, the predicted exam score increases by $3.2$ points."},{"key":"C","text":"A student who watches no television per week is predicted to score $89$ on the exam."},{"key":"D","text":"For each additional point on the exam, the student is predicted to watch $3.2$ fewer hours of television per week."}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $-3.2$, which means for each one-unit increase in $x$ (one additional hour of television per week), the predicted value of $y$ (exam score) changes by $-3.2$ points — a decrease of $3.2$ points. The interpretation that the score increases by $3.2$ points ignores the negative sign of the slope. The interpretation about scoring $89$ with no television describes the $y$-intercept, not the slope. The interpretation reversing the variables — predicting television hours from exam points — incorrectly swaps the roles of the dependent and independent variables.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29H7WT7', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'$$\\begin{cases} 4x - 6y = 14 \\\\ -6x + 9y = k \\end{cases}$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2B7W3IM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylindrical water tank has a diameter of $6$ feet and a height of $11$ feet. What is the volume of the tank?', NULL, $lyceon_json$[{"key":"A","text":"$33\\pi$ cubic feet"},{"key":"B","text":"$66\\pi$ cubic feet"},{"key":"C","text":"$99\\pi$ cubic feet"},{"key":"D","text":"$396\\pi$ cubic feet"}]$lyceon_json$::jsonb, 'C', NULL, E'The radius is $\\frac{6}{2} = 3$ feet. The volume of a cylinder is $V = \\pi r^2 h = \\pi(3^2)(11) = 99\\pi$ cubic feet. The distractor $33\\pi$ results from using $V = \\pi r h = \\pi(3)(11) = 33\\pi$, forgetting to square the radius. The distractor $66\\pi$ comes from computing the lateral surface area $2\\pi r h = 2\\pi(3)(11) = 66\\pi$ instead of the volume. The distractor $396\\pi$ arises from using the diameter as the radius: $\\pi(6^2)(11) = 396\\pi$.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C85TGW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A cone has a height of $35$ and a slant height of $37$. The volume of the cone can be written as $k\\pi$ cubic units. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1680', ARRAY['1680'], E'The radius $r$ of the cone is found using the Pythagorean theorem with the height and slant height: $r^2 + 35^2 = 37^2$, so $r^2 = 1369 - 1225 = 144$ and $r = 12$. The volume of a cone is $V = \\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(144)(35) = \\frac{5040\\pi}{3} = 1680\\pi$. Therefore $k = 1680$. A common error is forgetting the $\\frac{1}{3}$ factor and computing $\\pi(144)(35) = 5040\\pi$, giving $k = 5040$. Another error is using the slant height instead of the height, computing $\\frac{1}{3}\\pi(144)(37) = 1776\\pi$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EBDLPF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'If the system of equations $y = 2x^2 - 9x + 4$ and $y = 3x - 5$ has two solutions $(x_1, y_1)$ and $(x_2, y_2)$, what is the value of $x_1 + x_2$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Set the equations equal: $2x^2 - 9x + 4 = 3x - 5$. Rearranging gives $2x^2 - 12x + 9 = 0$. By Vieta''s formulas, the sum of the roots is $x_1 + x_2 = \\frac{12}{2} = 6$. No need to find individual roots; the sum follows directly from the coefficients of the combined quadratic.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EBIDXF', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $8x - 23 > 17$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'D', NULL, E'Solving $8x - 23 > 17$: add $23$ to both sides to get $8x > 40$, then divide by $8$ to get $x > 5$. Only $7$ is greater than $5$. The value $5$ fails because the inequality is strict ($>$, not $\\geq$), so $8(5) - 23 = 17$, which is not greater than $17$. The value $4$ gives $8(4) - 23 = 9$, which is not greater than $17$. The value $3$ gives $8(3) - 23 = 1$, which is not greater than $17$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EEUZDL', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'$$\\begin{cases} 3x + 2y = 23 \\\\ 5x - 2y = 17 \\end{cases}$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ERTLNM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university researcher found that students who ate breakfast every day had a mean GPA of $3.41$, compared to a mean GPA of $2.87$ for students who skipped breakfast most days. The study was conducted by surveying 500 students about their breakfast habits and collecting their GPA records. Which of the following is the most appropriate conclusion from this study?', NULL, $lyceon_json$[{"key":"A","text":"Eating breakfast every day causes students to achieve higher GPAs."},{"key":"B","text":"There is an association between eating breakfast daily and having a higher GPA among the surveyed students."},{"key":"C","text":"Students who skip breakfast should start eating breakfast every day to improve their GPAs."},{"key":"D","text":"The survey proves that breakfast has no meaningful effect on academic performance."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the study is observational — students were not randomly assigned to eat or skip breakfast — the researcher can only conclude that an association exists between daily breakfast consumption and higher GPA. The distractor claiming causation is inappropriate because observational studies cannot establish cause and effect; confounding variables (such as sleep habits, socioeconomic status, or general health consciousness) may explain the difference. The distractor recommending that students change their behavior to improve GPAs makes a prescriptive causal claim that the observational design cannot support. The distractor claiming the survey proves no effect directly contradicts the observed data showing a GPA difference of $3.41$ versus $2.87$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EX9XBC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation of a circle is $x^2 + y^2 - 14x + 6y + 22 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$3\\sqrt{3}$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$36$"}]$lyceon_json$::jsonb, 'B', NULL, E'Complete the square: $(x^2 - 14x + 49) + (y^2 + 6y + 9) = -22 + 49 + 9$, giving $(x - 7)^2 + (y + 3)^2 = 36$. The radius is $\\sqrt{36} = 6$. The distractor $3\\sqrt{3}$ arises from omitting the $+9$ when completing the $y$-square on the right side, yielding $r^2 = -22 + 49 = 27$ and $r = \\sqrt{27} = 3\\sqrt{3}$. The distractor $7$ comes from misidentifying the $x$-coordinate of the center as the radius. The distractor $36$ results from reporting $r^2 = 36$ instead of taking the square root to find $r$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
