INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HEN2FW', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'The sum of three consecutive odd integers is $183$. What is the largest of these three integers?', NULL, $lyceon_json$[{"key":"A","text":"$59$"},{"key":"B","text":"$61$"},{"key":"C","text":"$63$"},{"key":"D","text":"$65$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let the three consecutive odd integers be $x$, $x + 2$, and $x + 4$. Then $x + (x + 2) + (x + 4) = 183$, which simplifies to $3x + 6 = 183$, giving $3x = 177$ and $x = 59$. The three integers are $59$, $61$, and $63$, so the largest is $63$. The value $59$ comes from finding the smallest integer and reporting it instead of the largest. The value $61$ comes from reporting the middle integer. The value $65$ results from dropping the constant $6$ and solving $3x = 183$ to get $x = 61$, then computing $61 + 4 = 65$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HGNXDH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by $y = 8x + 47$, where $x$ is the number of hours studied and $y$ is the predicted test score. According to this model, what is the predicted test score for a student who studies for $6$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$48$"},{"key":"B","text":"$61$"},{"key":"C","text":"$95$"},{"key":"D","text":"$424$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 6$ into the equation: $y = 8(6) + 47 = 48 + 47 = 95$. The value $48$ results from computing only $8 \\times 6 = 48$ and omitting the intercept. The value $61$ results from adding instead of multiplying: $(8 + 6) + 47 = 14 + 47 = 61$. The value $424$ results from incorrect order of operations, adding before multiplying: $8 \\times (6 + 47) = 8 \\times 53 = 424$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HOCMUQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The ages, in years, of 5 volunteers at a community garden are $14$, $22$, $29$, $37$, and $41$. What is the median age of the volunteers?', NULL, $lyceon_json$[{"key":"A","text":"$25.5$"},{"key":"B","text":"$28.6$"},{"key":"C","text":"$29$"},{"key":"D","text":"$33$"}]$lyceon_json$::jsonb, 'C', NULL, E'With 5 values listed in order, the median is the 3rd value, which is $29$. The value $25.5$ results from averaging the 2nd and 3rd values, $(22 + 29)/2 = 25.5$, as if there were an even number of data points. The value $28.6$ results from computing the mean instead of the median: $(14 + 22 + 29 + 37 + 41)/5 = 143/5 = 28.6$. The value $33$ results from averaging the 3rd and 4th values, $(29 + 37)/2 = 33$, selecting the wrong pair.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HOHUI3', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'For $a = 7$ and $b = 3$, which expression gives the same value as $\\frac{a^2b - ab^2}{a^2 - 2ab + b^2}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{ab}{a - b}$"},{"key":"B","text":"$\\frac{ab}{a + b}$"},{"key":"C","text":"$\\frac{a + b}{ab}$"},{"key":"D","text":"$\\frac{a}{a - b}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the numerator: $a^2b - ab^2 = ab(a - b)$. Factor the denominator: $a^2 - 2ab + b^2 = (a - b)^2$. Dividing gives $\\frac{ab(a - b)}{(a - b)^2} = \\frac{ab}{a - b}$. Verification: with $a = 7, b = 3$, this equals $\\frac{21}{4}$, and the original expression gives $\\frac{147 - 63}{49 - 42 + 9} = \\frac{84}{16} = \\frac{21}{4}$. The expression $\\frac{ab}{a + b}$ results from incorrectly factoring the denominator as $(a + b)^2$ instead of $(a - b)^2$, giving $\\frac{21}{10}$. The expression $\\frac{a + b}{ab}$ inverts the fraction and uses the wrong sign, giving $\\frac{10}{21}$. The expression $\\frac{a}{a - b}$ drops the factor of $b$ from the numerator during cancellation, giving $\\frac{7}{4}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HRXHU6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, one of the acute angles is $\\theta$ and $\\sin(\\theta) = \\frac{36}{85}$. What is $\\cos(\\theta)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{36}{77}$"},{"key":"B","text":"$\\frac{49}{85}$"},{"key":"C","text":"$\\frac{77}{85}$"},{"key":"D","text":"$\\frac{36}{85}$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $\\sin(\\theta) = \\frac{36}{85}$, the opposite side is $36$ and the hypotenuse is $85$. The adjacent side is $\\sqrt{85^2 - 36^2} = \\sqrt{7225 - 1296} = \\sqrt{5929} = 77$. Therefore $\\cos(\\theta) = \\frac{77}{85}$. The distractor $\\frac{36}{77}$ results from computing $\\tan(\\theta) = \\frac{\\text{opposite}}{\\text{adjacent}} = \\frac{36}{77}$ instead of cosine. The distractor $\\frac{49}{85}$ comes from subtracting numerators ($85 - 36 = 49$) instead of using the Pythagorean theorem. The distractor $\\frac{36}{85}$ simply repeats the given sine value, confusing sine with cosine.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IZFH0X', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of length $15$ and $112$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$111$"},{"key":"B","text":"$113$"},{"key":"C","text":"$115$"},{"key":"D","text":"$127$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using the Pythagorean theorem: $c^2 = 15^2 + 112^2 = 225 + 12544 = 12769$. Taking the square root: $c = \\sqrt{12769} = 113$. The hypotenuse is $113$. The value $111$ results from subtracting instead of adding the squared legs. The value $115$ comes from an incorrect shortcut. The value $127$ comes from simply adding the two legs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IZPLQ1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $18$ centimeters. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$18\\pi$ square centimeters"},{"key":"B","text":"$81\\pi$ square centimeters"},{"key":"C","text":"$162\\pi$ square centimeters"},{"key":"D","text":"$324\\pi$ square centimeters"}]$lyceon_json$::jsonb, 'B', NULL, E'The radius is $\\frac{18}{2} = 9$ cm. The area is $\\pi r^2 = \\pi(9^2) = 81\\pi$ square centimeters. The distractor $18\\pi$ results from computing the circumference $2\\pi r = 2\\pi(9) = 18\\pi$ instead of the area. The distractor $162\\pi$ comes from using the formula $2\\pi r^2 = 2\\pi(81) = 162\\pi$, incorrectly doubling the area. The distractor $324\\pi$ arises from using the diameter as the radius: $\\pi(18^2) = 324\\pi$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JMQF60', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many real solutions does the equation $3x^2 + 14x + 19 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Use the discriminant $\\Delta = b^2 - 4ac = 14^2 - 4(3)(19) = 196 - 228 = -32$. Since $\\Delta < 0$, the equation has $0$ real solutions. Choosing $1$ solution reflects the misconception that a negative discriminant yields exactly one solution (confusing it with $\\Delta = 0$). Choosing $2$ solutions likely comes from assuming all quadratics have two real roots. Choosing $3$ solutions reflects a fundamental misunderstanding, since a quadratic can have at most $2$ real roots.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JWD7AX', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $x$-intercept of the line $3x + 7y = 21$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 3)$"},{"key":"B","text":"$(3, 0)$"},{"key":"C","text":"$(7, 0)$"},{"key":"D","text":"$(21, 0)$"}]$lyceon_json$::jsonb, 'C', NULL, E'The $x$-intercept occurs where $y = 0$. Substituting $y = 0$ into $3x + 7(0) = 21$ gives $3x = 21$, so $x = 7$. The $x$-intercept is $(7, 0)$. The point $(0, 3)$ is the $y$-intercept, found by setting $x = 0$ instead of $y = 0$. The point $(3, 0)$ results from dividing $21$ by the coefficient $7$ (the coefficient of $y$) instead of $3$. The point $(21, 0)$ results from setting $y = 0$ but failing to divide by $3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K5SWQZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A factory produces bolts at a constant rate. In the first $23$ minutes of operation, the factory produces $161$ bolts. At this same rate, how many bolts does the factory produce in $37$ minutes?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '259', ARRAY['259'], E'The production rate is $\\frac{161}{23} = 7$ bolts per minute. In $37$ minutes, the factory produces $7 \\times 37 = 259$ bolts. The computation requires first finding the unit rate by dividing the total output by the time, then applying that rate to the new time period. A common error is dividing $161$ by $37$ or setting up the proportion incorrectly, which would yield incorrect values.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KKERCI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A polling organization surveys a random sample of 350 registered voters and finds that $47\\%$ support Candidate X, with a margin of error of $\\pm 3.8$ percentage points. A second poll of 1,400 registered voters from the same population finds that $44\\%$ support Candidate X, with a margin of error of $\\pm 1.9$ percentage points. Which of the following statements is best supported by these two polls?', NULL, $lyceon_json$[{"key":"A","text":"The two polls contradict each other because the sample proportions are different."},{"key":"B","text":"The confidence intervals from the two polls overlap, so the results are consistent with each other."},{"key":"C","text":"The second poll is less reliable because it produced a lower estimate."},{"key":"D","text":"The first poll is more accurate because its sample proportion is closer to $50\\%$."}]$lyceon_json$::jsonb, 'B', NULL, E'The first poll gives a confidence interval of $(43.2\\%, 50.8\\%)$ and the second gives $(42.1\\%, 45.9\\%)$. These intervals overlap in the range $(43.2\\%, 45.9\\%)$, meaning the polls are statistically consistent — the difference in sample proportions is within the expected range of sampling variability. The distractor claiming contradiction fails to account for margin of error: different sample proportions do not imply inconsistency when confidence intervals overlap. The distractor calling the second poll less reliable confuses the estimate''s value with reliability — a larger sample actually produces a smaller margin of error and thus greater precision. The distractor about the first poll being more accurate because $47\\%$ is closer to $50\\%$ confuses proximity to $50\\%$ with accuracy, which depends on sample size and methodology.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L3XVSD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The table below shows the number of books read during a semester by each of 20 students.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L60TB3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains 9 lemon candies, 14 strawberry candies, and 8 mint candies. If one candy is selected at random, what is the probability of selecting a strawberry candy?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{14}{31}$"},{"key":"B","text":"$\\frac{14}{23}$"},{"key":"C","text":"$\\frac{9}{31}$"},{"key":"D","text":"$\\frac{7}{31}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of candies is $9 + 14 + 8 = 31$. The probability of selecting a strawberry candy is $\\frac{14}{31}$. The distractor $\\frac{14}{23}$ results from omitting the 8 mint candies from the total, using only $9 + 14 = 23$ as the denominator. The distractor $\\frac{9}{31}$ results from reading the count for lemon candies instead of strawberry. The distractor $\\frac{7}{31}$ results from an arithmetic slip of halving 14 to get 7 while keeping the correct total.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L9VBKY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A researcher takes a random sample of 150 teenagers in a large city and calculates a $95\\%$ confidence interval of $(4.3, 5.1)$ hours for the mean daily screen time of all teenagers in the city. Which of the following correctly interprets this confidence interval?', NULL, $lyceon_json$[{"key":"A","text":"$95\\%$ of all teenagers in the city have daily screen time between $4.3$ and $5.1$ hours."},{"key":"B","text":"If the sampling procedure were repeated many times, approximately $95\\%$ of the resulting confidence intervals would contain the true mean daily screen time of all teenagers in the city."},{"key":"C","text":"The probability that the true mean daily screen time is between $4.3$ and $5.1$ hours is $0.95$."},{"key":"D","text":"If another sample of 150 teenagers is selected, exactly $95\\%$ of their individual screen times will fall between $4.3$ and $5.1$ hours."}]$lyceon_json$::jsonb, 'B', NULL, E'The correct frequentist interpretation is that if the sampling procedure were repeated many times, about $95\\%$ of the constructed confidence intervals would capture the true population mean. The distractor claiming $95\\%$ of all teenagers fall in the range confuses a confidence interval for the mean with a prediction interval for individual values. The distractor assigning a $0.95$ probability to the true mean being in the interval treats the fixed (but unknown) parameter as a random variable — the true mean either is or is not in the interval; the $95\\%$ refers to the long-run success rate of the method. The distractor about $95\\%$ of individual screen times again confuses the mean with individual observations and misapplies the confidence level.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LI3BQ5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A wildlife biologist counts deer and elk in a forest preserve and finds that for every 5 deer, there are 3 elk. If the biologist counted 45 elk in the preserve, how many deer are there?', NULL, $lyceon_json$[{"key":"A","text":"$15$"},{"key":"B","text":"$27$"},{"key":"C","text":"$75$"},{"key":"D","text":"$225$"}]$lyceon_json$::jsonb, 'C', NULL, E'The ratio of deer to elk is $5:3$. With 45 elk, the scale factor is $\\frac{45}{3} = 15$. Multiplying the deer portion by this factor gives $5 \\times 15 = 75$ deer. The value $15$ results from finding the scale factor but reporting it as the answer instead of multiplying by 5. The value $27$ results from inverting the ratio and computing $\\frac{45 \\times 3}{5} = 27$, applying the elk ratio to the elk count. The value $225$ results from multiplying $45 \\times 5 = 225$ without dividing by the elk portion of the ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LIJL1Z', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company tests a new medication by randomly assigning 600 patients to receive either the medication or a placebo. The study finds a statistically significant reduction in symptoms among patients receiving the medication compared to the placebo group. However, all 600 patients were recruited from a single hospital in one city. Which of the following is the most valid concern about this study?', NULL, $lyceon_json$[{"key":"A","text":"The random assignment of patients to groups means the study's results cannot be trusted."},{"key":"B","text":"The study can support a causal claim about the medication's effect on the participants, but the results may not generalize to all patients."},{"key":"C","text":"The study should have used an observational design instead of a randomized experiment."},{"key":"D","text":"The use of a placebo group invalidates the findings because those patients received no active treatment."}]$lyceon_json$::jsonb, 'B', NULL, E'Random assignment allows the study to establish a causal relationship between the medication and symptom reduction within the study population. However, because all participants came from a single hospital, the sample may not represent the broader population of all patients, limiting generalizability. The distractor dismissing the results because of random assignment misunderstands its purpose — random assignment strengthens internal validity by balancing confounding variables across groups. The distractor suggesting an observational design contradicts sound methodology: randomized experiments are the gold standard for establishing causation and would not be improved by removing random assignment. The distractor about the placebo group invalidating results misunderstands the role of a placebo — it serves as a control to isolate the medication''s effect from the placebo effect and natural symptom changes.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MEGK6A', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h(x) = -2(x + 4)^2 + 11$ is defined for all real numbers. Which of the following statements is true?', NULL, $lyceon_json$[{"key":"A","text":"The function $h$ has a minimum value of $11$."},{"key":"B","text":"The function $h$ has a maximum value of $11$."},{"key":"C","text":"The function $h$ has a maximum value of $-4$."},{"key":"D","text":"The function $h$ has a minimum value of $-4$."}]$lyceon_json$::jsonb, 'B', NULL, E'The function $h(x) = -2(x + 4)^2 + 11$ is in vertex form with $a = -2 < 0$, so the parabola opens downward and the vertex represents a maximum. The vertex is at $(-4, 11)$, so the maximum value is $11$. Stating the function has a minimum of $11$ incorrectly identifies the extremum type — a downward parabola has no minimum. Stating the maximum is $-4$ confuses the $x$-coordinate of the vertex with the function''s output value. Stating the minimum is $-4$ makes both errors: wrong extremum type and wrong coordinate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O7GTF1', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The total cost, in dollars, of renting a kayak for $x$ hours is modeled by the function $g(x) = mx + 14$, where $m$ is a constant. If renting a kayak for $4$ hours costs $\\$42$, what is the value of $m$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$7$"},{"key":"C","text":"$\\frac{21}{2}$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since $g(4) = 42$, we have $4m + 14 = 42$. Subtracting $14$ from both sides gives $4m = 28$, so $m = 7$. The value $2$ results from dividing $28$ by the base fee $14$ instead of by $4$. The value $\\frac{21}{2}$ results from dividing the total cost $42$ by $4$ without subtracting the base fee, getting $\\frac{42}{4} = \\frac{21}{2}$. The value $14$ results from adding the base fee instead of subtracting it: $4m = 42 + 14 = 56$, then $m = 14$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OPBWTJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A store has $200$ items on display. If $17\\%$ of the items are marked for clearance, how many items are marked for clearance?', NULL, $lyceon_json$[{"key":"A","text":"$17$"},{"key":"B","text":"$34$"},{"key":"C","text":"$166$"},{"key":"D","text":"$183$"}]$lyceon_json$::jsonb, 'B', NULL, E'Finding $17\\%$ of $200$: $0.17 \\times 200 = 34$ items are marked for clearance. The value $17$ results from reporting the percentage itself as the count of items, without performing any calculation. The value $166$ results from computing the number of items NOT on clearance: $200 - 34 = 166$, answering the opposite of what was asked. The value $183$ results from subtracting the percentage directly from the total: $200 - 17 = 183$, treating the percent as a count to subtract.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PG7J17', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 400 voters in a city found that $58\\%$ support a new park initiative. The margin of error for this estimate is $\\pm 4$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $58\\%$ of all voters in the city support the initiative."},{"key":"B","text":"Between $54\\%$ and $62\\%$ of the 400 sampled voters support the initiative."},{"key":"C","text":"It is plausible that between $54\\%$ and $62\\%$ of all voters in the city support the initiative."},{"key":"D","text":"At least $62\\%$ of all voters in the city support the initiative."}]$lyceon_json$::jsonb, 'C', NULL, E'A margin of error of $\\pm 4$ percentage points means the confidence interval for the true population proportion extends from $58\\% - 4\\% = 54\\%$ to $58\\% + 4\\% = 62\\%$. The correct interpretation is that the true percentage of all voters supporting the initiative plausibly falls in this range. The distractor stating exactly $58\\%$ ignores sampling variability entirely. The distractor applying the interval to the sample confuses the population parameter with the sample statistic — the sample result is already known to be $58\\%$. The distractor claiming at least $62\\%$ uses only the upper bound and misinterprets the interval as a minimum.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PLBQUI', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{4x^2 + 20x + 25}{2x + 5}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 5$"},{"key":"B","text":"$2x - 5$"},{"key":"C","text":"$4x + 5$"},{"key":"D","text":"$2x + 25$"}]$lyceon_json$::jsonb, 'A', NULL, E'The numerator $4x^2 + 20x + 25$ is a perfect square trinomial: $(2x + 5)^2$. Dividing $(2x + 5)^2$ by $(2x + 5)$ gives $2x + 5$. The expression $2x - 5$ results from incorrectly applying a negative sign during factoring. The expression $4x + 5$ comes from dividing only the first and last terms of the numerator by the denominator without proper factoring. The expression $2x + 25$ arises from dividing $4x^2$ by $2x$ correctly but failing to simplify $\\frac{25}{1}$ and instead appending $25$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QFMN8S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A student answered $43$ out of $50$ questions correctly on a test. What percent of the questions did the student answer correctly?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '86', ARRAY['86'], E'The fraction correct is $\\frac{43}{50}$. Converting to a percentage: $\\frac{43}{50} \\times 100 = 86\\%$. Alternatively, $\\frac{43}{50} = 0.86$, and $0.86 \\times 100 = 86$. A common error is dividing $50$ by $43$ (approximately $1.16$) and misinterpreting the result, or computing $\\frac{43}{50}$ as a decimal and omitting the conversion to a percentage.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QT58GZ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $f$ models the total cost, in dollars, of a delivery based on the distance traveled. The function satisfies $f(9) = 38$ and $f(17) = 62$. According to the model, what is the value of $f(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$11$"},{"key":"C","text":"$14$"},{"key":"D","text":"$24$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since $f$ is linear, the rate of change is $\\frac{f(17) - f(9)}{17 - 9} = \\frac{62 - 38}{8} = \\frac{24}{8} = 3$ dollars per mile. Using the point $(9, 38)$: $f(x) = 3x + b$, so $38 = 3(9) + b = 27 + b$, giving $b = 11$. Therefore $f(0) = 11$. The value $3$ is the rate of change of $f$, not $f(0)$, and results from misreading what the question asks. The value $14$ results from subtracting the output difference from the first output ($38 - 24 = 14$) without computing the rate of change. The value $24$ results from finding only the output difference ($62 - 38 = 24$) and stopping there without dividing by the input difference or solving for $f(0)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QUGB2I', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'A surveyor stands $83$ meters from the base of a building. The angle of elevation to the top of the building is $\\alpha$, where $\\tan(\\alpha) = \\frac{19}{83}$. The angle of elevation to the top of a flagpole on the roof is $\\beta$, where $\\tan(\\beta) = \\frac{23}{83}$. What is the height, in meters, of the flagpole?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Using the tangent ratio, the height of the building is $83 \\times \\frac{19}{83} = 19$ meters. The total height from the ground to the top of the flagpole is $83 \\times \\frac{23}{83} = 23$ meters. The flagpole height is $23 - 19 = 4$ meters. A common error is computing only one height and reporting $19$ or $23$, or misapplying the tangent ratio by dividing $83$ by the tangent value instead of multiplying.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RLH7QH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A company surveyed 200 employees about commute method and department. Of the 200 employees, 53 are in Marketing and 147 are in Engineering. Among Marketing employees, 19 bike to work. Among Engineering employees, 41 bike to work. If an employee is selected at random from those who bike to work, what is the probability that the employee is in Marketing?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{60}$"},{"key":"B","text":"$\\frac{19}{53}$"},{"key":"C","text":"$\\frac{19}{200}$"},{"key":"D","text":"$\\frac{41}{60}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of employees who bike is $19 + 41 = 60$. Given that the selected employee bikes, the probability of being in Marketing is $\\frac{19}{60}$. The distractor $\\frac{19}{53}$ confuses the conditional direction, computing $P(\\text{bike} \\mid \\text{Marketing}) = \\frac{19}{53}$ instead of $P(\\text{Marketing} \\mid \\text{bike})$. The distractor $\\frac{19}{200}$ uses the entire survey population as the denominator rather than restricting to bikers. The distractor $\\frac{41}{60}$ correctly identifies 60 total bikers but selects the Engineering bikers instead of Marketing bikers.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S5QZ7C', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A bag contains 5 red tokens, 6 blue tokens, and 4 yellow tokens. Two tokens are drawn at random without replacement. What is the probability that exactly one of the two tokens drawn is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{12}{35}$"},{"key":"B","text":"$\\frac{9}{35}$"},{"key":"C","text":"$\\frac{18}{35}$"},{"key":"D","text":"$\\frac{2}{5}$"}]$lyceon_json$::jsonb, 'C', NULL, E'There are $5 + 6 + 4 = 15$ tokens total, of which 6 are blue and 9 are not blue. The probability of exactly one blue in two draws without replacement has two orderings: blue then not-blue, or not-blue then blue. This gives $2 \\times \\frac{6}{15} \\times \\frac{9}{14} = \\frac{108}{210} = \\frac{18}{35}$. The distractor $\\frac{9}{35}$ results from computing only one ordering ($\\frac{6}{15} \\times \\frac{9}{14} = \\frac{54}{210} = \\frac{9}{35}$) and forgetting to account for the second arrangement. The distractor $\\frac{12}{35}$ results from using 6 instead of 9 for the non-blue count: $2 \\times \\frac{6}{15} \\times \\frac{6}{14} = \\frac{72}{210} = \\frac{12}{35}$. The distractor $\\frac{2}{5}$ results from computing only the single-draw probability $\\frac{6}{15} = \\frac{2}{5}$ without considering the second draw.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SRH9KL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $DEF$, angle $D$ is twice angle $E$, and angle $F$ measures $51°$. What is the measure, in degrees, of angle $E$?', NULL, $lyceon_json$[{"key":"A","text":"$43$"},{"key":"B","text":"$51$"},{"key":"C","text":"$64.5$"},{"key":"D","text":"$86$"}]$lyceon_json$::jsonb, 'A', NULL, E'The angles of a triangle sum to $180°$. Let angle $E = x$; then angle $D = 2x$. The equation is $2x + x + 51 = 180$, giving $3x = 129$ and $x = 43$. The distractor $51$ comes from assuming angle $E$ equals angle $F$, ignoring the given relationship. The distractor $64.5$ arises from omitting angle $E$ in the equation, writing $2x + 51 = 180$, yielding $x = 64.5$. The distractor $86$ results from solving for angle $D = 2(43) = 86$ instead of angle $E$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UVNMH3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A chemical solution requires mixing compound X and compound Y in a ratio of $7:4$ by volume. A technician needs to prepare $550$ milliliters of the solution. How many milliliters of compound X are needed?', NULL, $lyceon_json$[{"key":"A","text":"$200$"},{"key":"B","text":"$275$"},{"key":"C","text":"$350$"},{"key":"D","text":"$385$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total number of parts in the ratio is $7 + 4 = 11$. Compound X accounts for $\\frac{7}{11}$ of the total volume, so $\\frac{7}{11} \\times 550 = 350$ milliliters. The value $200$ results from computing the amount of compound Y instead: $\\frac{4}{11} \\times 550 = 200$, answering with the wrong compound. The value $275$ results from dividing $550$ by $2$, ignoring the ratio entirely. The value $385$ results from incorrectly adding the ratio parts as $7 + 4 = 10$ instead of $11$, then computing $\\frac{7}{10} \\times 550 = 385$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V2MUPF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health researcher recruits 80 volunteers and randomly assigns 40 to participate in a new exercise program for 12 weeks while the other 40 continue their normal routine. At the end of 12 weeks, she compares the average blood pressure change between the two groups. This study design is best described as', NULL, $lyceon_json$[{"key":"A","text":"an observational study, because the researcher observed blood pressure changes over time"},{"key":"B","text":"a survey, because the participants were volunteers"},{"key":"C","text":"an experiment, because the researcher randomly assigned participants to treatment groups"},{"key":"D","text":"an observational study, because the participants volunteered rather than being selected at random from a population"}]$lyceon_json$::jsonb, 'C', NULL, E'The defining feature of an experiment is that the researcher imposes a treatment by randomly assigning subjects to groups. Here the researcher randomly assigned 40 participants to the exercise program and 40 to a control condition, making this an experiment. The distractor calling it observational because blood pressure was observed confuses the general act of measuring an outcome with the technical meaning of an observational study, which lacks random assignment to treatments. The distractor labeling it a survey confuses the recruitment method (volunteering) with the study design — surveys collect self-reported data without imposing treatments. The distractor citing volunteer participation confuses random selection (how participants enter the study) with random assignment (how participants are allocated to treatments); random assignment to groups is what makes a study an experiment, regardless of how participants were recruited.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VMOE65', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'If $3x + 7 > 19$ and $2x - 1 < 17$, how many integer values of $x$ satisfy both inequalities simultaneously?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'From the first inequality: $3x + 7 > 19$ gives $3x > 12$, so $x > 4$. From the second inequality: $2x - 1 < 17$ gives $2x < 18$, so $x < 9$. Combining both, $4 < x < 9$. The integers in this range are $5, 6, 7, 8$, giving $4$ integer values.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W162UC', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is the completely factored form of $3x^3 - 12x$?', NULL, $lyceon_json$[{"key":"A","text":"$3x(x^2 - 4)$"},{"key":"B","text":"$3x(x - 4)$"},{"key":"C","text":"$3(x^3 - 4x)$"},{"key":"D","text":"$3x(x + 2)(x - 2)$"}]$lyceon_json$::jsonb, 'D', NULL, E'Factor out $3x$ to get $3x(x^2 - 4)$. Then recognize $x^2 - 4$ as a difference of squares: $(x + 2)(x - 2)$. The completely factored form is $3x(x + 2)(x - 2)$. The expression $3x(x^2 - 4)$ is only partially factored because $x^2 - 4$ can be further factored as a difference of squares. The expression $3x(x - 4)$ incorrectly treats the constant term as $4$ rather than recognizing $x^2 - 4$ as a binomial. The expression $3(x^3 - 4x)$ only factors out the $3$ without extracting the common factor of $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WD2JBM', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'A line perpendicular to $2x + y = 9$ passes through the point $(4, 3)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$1$"},{"key":"C","text":"$5$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'B', NULL, E'Rewriting $2x + y = 9$ as $y = -2x + 9$ shows the slope is $-2$. The perpendicular slope is the negative reciprocal: $\\frac{1}{2}$. Using point-slope form: $y - 3 = \\frac{1}{2}(x - 4)$, which gives $y = \\frac{1}{2}x - 2 + 3 = \\frac{1}{2}x + 1$. The $y$-intercept is $1$. The value $-5$ results from using slope $2$ (the reciprocal without negating) and computing $y - 3 = 2(x - 4)$, giving $y = 2x - 5$. The value $5$ results from substituting $(x + 4)$ instead of $(x - 4)$ in the point-slope form: $y - 3 = \\frac{1}{2}(x + 4)$, giving $y = \\frac{1}{2}x + 5$. The value $11$ results from using the original slope $-2$ instead of the perpendicular slope: $y - 3 = -2(x - 4)$, giving $y = -2x + 11$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XE2V9J', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'$$\\begin{cases} x + y = 19 \\\\ x - y = 7 \\end{cases}$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XG1KME', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g(x) = (x - 7)^2 + 3$ has a minimum value. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$-7$"},{"key":"D","text":"$49$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $g(x) = (x - 7)^2 + 3$ is in vertex form $a(x - h)^2 + k$ where the vertex is $(7, 3)$. Since $a = 1 > 0$, the parabola opens upward and the minimum value is $k = 3$. Choosing $7$ confuses the $x$-coordinate of the vertex with the minimum value. Choosing $-7$ applies an incorrect sign change to the $x$-coordinate. Choosing $49$ computes $7^2$ instead of reading the constant term from vertex form.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y8Z4E8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $17$ meters and a width of $9$ meters. What is the area, in square meters, of the garden?', NULL, $lyceon_json$[{"key":"A","text":"$26$"},{"key":"B","text":"$52$"},{"key":"C","text":"$153$"},{"key":"D","text":"$162$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a rectangle is length times width: $17 \\times 9 = 153$ square meters. The distractor $26$ results from adding the dimensions ($17 + 9 = 26$) instead of multiplying. The distractor $52$ comes from computing the perimeter $2(17 + 9) = 52$ instead of the area. The distractor $162$ arises from an arithmetic slip, computing $18 \\times 9 = 162$ by rounding $17$ up to $18$.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YGQTYP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher measures the age (in months) and height (in centimeters) of $30$ seedlings. The line of best fit is $h = 1.7a + 4.3$, where $a$ is the age in months and $h$ is the predicted height in centimeters. One seedling is $9$ months old and has an actual height of $23.1$ centimeters. What is the residual for this seedling?', NULL, $lyceon_json$[{"key":"A","text":"$-3.5$"},{"key":"B","text":"$3.5$"},{"key":"C","text":"$15.3$"},{"key":"D","text":"$19.6$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted height for a $9$-month-old seedling is $h = 1.7(9) + 4.3 = 15.3 + 4.3 = 19.6$ centimeters. The residual is actual minus predicted: $23.1 - 19.6 = 3.5$. The value $-3.5$ results from reversing the subtraction order, computing predicted minus actual ($19.6 - 23.1 = -3.5$). The value $15.3$ results from computing only $1.7 \\times 9 = 15.3$ without adding the intercept, then stopping. The value $19.6$ results from computing the predicted value correctly but reporting it as the residual rather than subtracting it from the actual height.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20KVWX8', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the overall structure of the text?', E'The fruit fly Drosophila melanogaster has been a model organism in genetics research for over a century. Its genome was fully sequenced in 2000, revealing approximately 13,600 genes. Because many of these genes have human counterparts, researchers have used Drosophila to study diseases ranging from Parkinson''s to diabetes.', $lyceon_json$[{"key":"A","text":"It introduces a research subject, presents a key milestone in studying it, and explains why that subject remains scientifically valuable."},{"key":"B","text":"It describes a scientific controversy, outlines competing hypotheses, and identifies which hypothesis current evidence favors."},{"key":"C","text":"It compares two model organisms, evaluates their respective advantages, and recommends one over the other."},{"key":"D","text":"It narrates the discovery of a species, details the habitat in which it was found, and catalogs its physical traits."}]$lyceon_json$::jsonb, 'A', NULL, E'The text first introduces Drosophila as a long-used model organism, then notes the milestone of its genome being sequenced in 2000, and finally explains its ongoing value because its genes have human counterparts useful for disease research. The option describing a scientific controversy is wrong because the passage presents no competing hypotheses or debate. The option about comparing two organisms is wrong because only one organism, Drosophila, is discussed. The option about narrating a species discovery is wrong because the passage does not describe when or where the species was found or catalog its physical traits.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
