INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23LU9EO', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the documentary filmmaker Renata Osei arrived at the remote village in northern Ghana in 2019, the annual harvest festival she had planned to film _______ three days earlier due to an unexpected early monsoon season.', $lyceon_json$[{"key":"A","text":"had concluded"},{"key":"B","text":"has concluded"},{"key":"C","text":"was concluding"},{"key":"D","text":"concludes"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence describes two past events: Renata Osei''s arrival in 2019 and the festival''s conclusion, which occurred before her arrival. The past perfect tense ("had concluded") is required to indicate that the festival ended prior to the already-past event of her arrival. "Has concluded" uses the present perfect, which links a past action to the present moment—inappropriate here because both events are set firmly in the past (2019). "Was concluding" uses the past progressive, which would imply the festival was in the process of ending at the moment she arrived, contradicting the phrase "three days earlier," which indicates the conclusion was already complete. "Concludes" uses the simple present tense, which is entirely inconsistent with the past-tense narrative context established by "arrived" and "had planned."', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW245MEXW', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "temper" most nearly mean?', E'Metallurgist Anouk van der Berg has shown that adding trace quantities of niobium—as little as 0.03 percent by mass—can temper the brittleness of high-carbon steel alloys without diminishing their hardness. Her 2023 study demonstrated that niobium atoms migrate to grain boundaries during annealing, forming carbide precipitates that redistribute internal stress and prevent crack propagation along crystallographic planes.', $lyceon_json$[{"key":"A","text":"heat"},{"key":"B","text":"enrage"},{"key":"C","text":"moderate"},{"key":"D","text":"forge"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes how niobium reduces brittleness without eliminating hardness. "Moderate" means to lessen or reduce the intensity of something, which captures the idea of partially diminishing brittleness while preserving other properties. "Heat" refers to raising temperature—a physical action unrelated to reducing a quality like brittleness. "Enrage" means to provoke fury, an emotional meaning that produces nonsense when applied to brittleness. "Forge" means to shape metal by hammering or to fabricate, but the passage is discussing a chemical reduction of a material property, not a shaping process.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW247LBG5', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "precipitated" most nearly mean?', E'Ornithologist Lydia Fernholm has argued that the 2017 collapse of herring populations in the northern Baltic did not directly starve seabird colonies but instead precipitated a cascade of behavioral changes: terns shifted to smaller prey, puffins extended foraging ranges by forty kilometers, and guillemots abandoned historically productive nesting cliffs in favor of more sheltered sites closer to remaining fish stocks.', $lyceon_json$[{"key":"A","text":"condensed"},{"key":"B","text":"hastened"},{"key":"C","text":"triggered"},{"key":"D","text":"dissolved"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage states that the herring collapse did not directly starve colonies but instead set off a series of behavioral changes. "Triggered" means to cause or initiate a process, which matches this causal relationship. "Condensed" means to compress or reduce in volume, which is incoherent in this context of causing behavioral changes. "Hastened" means to speed up something already in progress, but the passage describes the collapse as initiating entirely new behaviors rather than accelerating existing ones. "Dissolved" means to break apart or disintegrate, which produces a nonsensical meaning when substituted into the sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24EW9KO', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'While the fruit fly Drosophila melanogaster has long served as a model organism in genetics, researchers at the University of Zurich have recently turned to a less conventional subject: the marbled crayfish. __________ the marbled crayfish reproduces through parthenogenesis, producing genetically identical offspring, which makes it uniquely valuable for studying epigenetic variation without the confounding variable of genetic differences.', E'While the fruit fly Drosophila melanogaster has long served as a model organism in genetics, researchers at the University of Zurich have recently turned to a less conventional subject: the marbled crayfish. __________ the marbled crayfish reproduces through parthenogenesis, producing genetically identical offspring, which makes it uniquely valuable for studying epigenetic variation without the confounding variable of genetic differences.', $lyceon_json$[{"key":"A","text":"Specifically,"},{"key":"B","text":"Nonetheless,"},{"key":"C","text":"Coincidentally,"},{"key":"D","text":"Alternatively,"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence elaborates on why the marbled crayfish is valuable, providing a specific detail that explains the researchers'' choice. The transition "Specifically," correctly signals that what follows is a clarifying detail about the preceding claim. "Nonetheless" incorrectly introduces a concession where none exists, since the second sentence supports rather than contradicts the first. "Coincidentally" wrongly implies the crayfish''s trait is a matter of chance unrelated to the researchers'' interest, when in fact it is the reason for their interest. "Alternatively" wrongly suggests the crayfish is being presented as a different option rather than as a subject whose specific trait is being explained.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25491JZ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'Economist Priya Venkataraman has proposed that the persistent wage gap between urban and rural workers in developing economies cannot be explained solely by differences in human capital or labor productivity. Venkataraman''s model incorporates what she calls ''spatial sorting''—the tendency for workers with higher unobserved ability to migrate to cities, leaving rural labor markets composed disproportionately of less productive individuals. Crucially, however, Venkataraman distinguishes her framework from simple selection effects: she argues that urban environments themselves amplify productivity through dense networks of knowledge exchange, meaning that identical workers would perform differently depending on location. The implication is paradoxical: policies designed to equalize wages by subsidizing rural employment may inadvertently widen the gap by reducing the incentive for high-ability workers to relocate to cities where their productivity would be magnified.', $lyceon_json$[{"key":"A","text":"Venkataraman argues that both worker self-selection and location-specific productivity gains contribute to the urban-rural wage gap, and that naive equalization policies may backfire."},{"key":"B","text":"Venkataraman's research demonstrates that rural workers are inherently less productive than urban workers regardless of the environment in which they work."},{"key":"C","text":"Venkataraman has shown that spatial sorting alone accounts for the persistent wage disparities between urban and rural areas in developing economies."},{"key":"D","text":"Venkataraman recommends that developing economies discontinue rural employment subsidies in order to accelerate urbanization and economic growth."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Venkataraman''s dual-mechanism model: spatial sorting (self-selection of high-ability workers into cities) combined with location-specific productivity amplification. It also notes a paradoxical policy implication. The option referencing both self-selection and location-specific productivity gains, along with the backfire risk, accurately captures the full argument. The option claiming rural workers are inherently less productive contradicts the text''s explicit point that identical workers would perform differently depending on location—it is location, not inherent ability, that matters. The option attributing the gap to spatial sorting alone ignores the passage''s crucial distinction that urban environments themselves amplify productivity beyond mere selection effects. The option about recommending discontinuation of subsidies overstates the passage, which describes a paradoxical implication but does not present an explicit policy recommendation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25NGI19', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Archaeologist Kseniya Murasheva''s 2021 excavation of a Bronze Age settlement near Volgograd uncovered ceramics with pigment patterns consistent with long-distance trade networks stretching to the southern Caucasus. __________ chemical analysis of the clay composition revealed that the vessels were manufactured locally, suggesting that the decorative techniques, rather than the objects themselves, had traveled along those routes.', E'Archaeologist Kseniya Murasheva''s 2021 excavation of a Bronze Age settlement near Volgograd uncovered ceramics with pigment patterns consistent with long-distance trade networks stretching to the southern Caucasus. __________ chemical analysis of the clay composition revealed that the vessels were manufactured locally, suggesting that the decorative techniques, rather than the objects themselves, had traveled along those routes.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"In other words,"},{"key":"C","text":"However,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first sentence establishes that the ceramics'' pigment patterns suggest long-distance trade of goods, while the second sentence reveals that the clay was local, meaning the objects themselves did not travel. This contrast between the expected interpretation (traded goods) and the actual finding (traded techniques) requires a concessive or contrastive transition. "However" correctly signals this reversal. "Furthermore" incorrectly implies the second sentence adds a supporting detail, when it actually qualifies the initial impression. "In other words" incorrectly suggests a restatement, but the second sentence introduces new, contrasting evidence rather than restating the first. "For instance" incorrectly frames the chemical analysis as an example of the trade networks claim, when it actually complicates that claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26U4U1Z', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly weaken the claim made by Okoro and Salinas?', E'Political scientists Okoro and Salinas argue that ranked-choice voting (RCV) in municipal elections reduces negative campaigning. Their reasoning is that under RCV, candidates have an incentive to appeal to supporters of rival candidates for second- and third-choice rankings, which discourages attack-oriented strategies. Okoro and Salinas base their claim primarily on a survey of 1,700 voters across eleven cities that adopted RCV between 2016 and 2021, in which respondents reported perceiving less negativity in campaigns conducted under RCV than in prior plurality elections.', $lyceon_json$[{"key":"A","text":"An independent content analysis of campaign advertisements in the same eleven cities found no statistically significant reduction in the proportion of negative ads after those cities adopted RCV."},{"key":"B","text":"Voters in cities that use plurality voting report similar levels of satisfaction with local government as voters in RCV cities."},{"key":"C","text":"Several national political organizations have endorsed ranked-choice voting as a reform that promotes more civil discourse."},{"key":"D","text":"In three of the eleven cities studied, voter turnout increased by more than fifteen percent after the adoption of RCV."}]$lyceon_json$::jsonb, 'A', NULL, E'Okoro and Salinas claim that RCV reduces negative campaigning, relying on voter perceptions. The finding that an independent content analysis of actual campaign ads showed no significant reduction in negativity directly contradicts the claim by providing objective evidence that negative campaigning did not decrease, suggesting voter perceptions may be unreliable. The finding about voter satisfaction with local government addresses a different outcome entirely and does not bear on the level of negative campaigning. The finding about national organizations endorsing RCV is an appeal to authority that says nothing about whether negativity actually decreased. The finding about increased voter turnout concerns participation rates, which is unrelated to whether campaigns became less negative.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
