INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CPMU00', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Each of the seventeen murals painted by the artist Tomoko Ishida on the exterior walls of the Greenvale Community Center _______ a different chapter in the neighborhood''s history, from the founding of its first cooperative market in 1923 to the opening of the public library in 2011.', $lyceon_json$[{"key":"A","text":"depict"},{"key":"B","text":"have depicted"},{"key":"C","text":"depicts"},{"key":"D","text":"are depicting"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is "Each," which is a singular indefinite pronoun. The prepositional phrase "of the seventeen murals painted by the artist Tomoko Ishida on the exterior walls of the Greenvale Community Center" modifies "Each" but does not change the number of the subject. A singular verb form is required. "Depicts" is the third-person singular present tense, correctly agreeing with "Each." "Depict" is a plural verb form that incorrectly agrees with the nearby plural noun "murals" rather than with the true subject "Each." "Have depicted" is also plural and additionally introduces an unnecessary shift to the present perfect tense. "Are depicting" is plural and uses the progressive aspect, which incorrectly suggests the depicting is ongoing or temporary rather than describing a permanent feature of the murals.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GOWH2N', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The geologist Maren Solvik has spent fourteen years studying volcanic sediment layers in Iceland. Her research has revealed that eruptions during the medieval period were far more frequent than previously _______ this finding has prompted other scientists to reexamine historical climate data from the region.', $lyceon_json$[{"key":"A","text":"estimated,"},{"key":"B","text":"estimated;"},{"key":"C","text":"estimated"},{"key":"D","text":"estimated and"}]$lyceon_json$::jsonb, 'B', NULL, E'The blank separates two independent clauses: one ending with the word "estimated" and one beginning with "this finding has prompted." A semicolon correctly joins two independent clauses without a coordinating conjunction. The option using only a comma creates a comma splice, which is a sentence boundary error. The option with no punctuation creates a run-on sentence by fusing the two clauses together. The option using "and" without a preceding comma fails to properly punctuate the compound sentence (a comma is needed before a coordinating conjunction joining two independent clauses).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HHCKV8', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In a 2019 study, archaeologist Fumiko Ikeda challenged the longstanding assumption that the Jōmon people of prehistoric Japan were purely hunter-gatherers. Ikeda''s analysis of carbon isotope ratios in charred residues from Jōmon pottery dating to approximately 5,800 years ago revealed signatures consistent with cultivated starchy plants, specifically foxtail millet. While Ikeda acknowledges that full-scale agriculture did not emerge in Japan until the later Yayoi period, she argues that the Jōmon evidence indicates a transitional phase of incipient cultivation—a deliberate, if limited, manipulation of plant growth that blurs the conventional boundary between foraging and farming.', $lyceon_json$[{"key":"A","text":"Ikeda's findings suggest that the Jōmon people practiced a form of early plant cultivation, complicating the traditional view of them as strict hunter-gatherers."},{"key":"B","text":"Ikeda's isotope analysis proved that Jōmon pottery was primarily used for storing cultivated grains rather than for cooking foraged foods."},{"key":"C","text":"The Jōmon period is now recognized by most archaeologists as the earliest phase of full-scale agriculture in East Asia."},{"key":"D","text":"Carbon isotope analysis is a more reliable method than traditional excavation for studying the diets of prehistoric populations."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Ikeda''s challenge to the assumption that Jōmon people were purely hunter-gatherers, presenting evidence of incipient cultivation that blurs the foraging-farming boundary. The option about early plant cultivation complicating the traditional view captures this central argument. The option about pottery being used primarily for storing cultivated grains overstates the findings—the text mentions charred residues consistent with cultivated plants but says nothing about storage purpose. The option claiming the Jōmon period is recognized as the earliest full-scale agriculture contradicts the text, which explicitly states full-scale agriculture did not emerge until the Yayoi period. The option about carbon isotope analysis being more reliable than excavation focuses on methodology, which is not the passage''s central concern.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I4Q9HJ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Entomologists at the University of São Paulo hypothesize that the sharp decline in populations of the orchid bee Eulaema nigrita in southeastern Brazil is driven primarily by the fragmentation of Atlantic Forest habitat rather than by pesticide exposure. They note that Eulaema nigrita requires large contiguous tracts of forest to maintain viable breeding populations because males of the species collect aromatic compounds from widely dispersed orchid species to assemble the chemical bouquets used in mating displays.', $lyceon_json$[{"key":"A","text":"Eulaema nigrita populations in large, unbroken forest reserves have remained stable over the past two decades, while populations in fragmented patches of similar total area have declined sharply."},{"key":"B","text":"Pesticide concentrations in southeastern Brazilian waterways have increased significantly since 2005."},{"key":"C","text":"Orchid bees in fragmented habitats have been observed visiting agricultural crops as alternative sources of aromatic compounds."},{"key":"D","text":"Several other bee species that do not depend on orchid-derived chemicals have also declined in fragmented Atlantic Forest areas."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers'' hypothesis is that habitat fragmentation, not pesticide exposure, drives the decline of Eulaema nigrita. The finding that populations remained stable in large unbroken reserves but declined in fragmented patches of similar total area directly supports fragmentation as the cause by isolating the variable of contiguity. The finding about increased pesticide concentrations would, if anything, support the alternative explanation (pesticide exposure) rather than the fragmentation hypothesis. The finding about bees visiting crops for aromatic compounds does not address whether fragmentation causes population decline—it describes a behavioral response but not a population outcome. The finding about other non-orchid-dependent bee species declining in fragmented areas would suggest fragmentation affects bees generally, but since those species lack the specific orchid-dependency mechanism described, it does not directly support the researchers'' particular hypothesis about Eulaema nigrita.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IKYVTA', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, the marine biologist Kenji Harada published a controversial paper arguing that deep-sea bioluminescent organisms use light signals not merely for attracting prey but also for coordinating _______ subsequent laboratory experiments by Harada and his colleague Yuki Watanabe confirmed this hypothesis, demonstrating that certain anglerfish species emit synchronized pulses when in proximity to one another.', $lyceon_json$[{"key":"A","text":"group behavior."},{"key":"B","text":"group behavior; however, subsequent"},{"key":"C","text":"group behavior,"},{"key":"D","text":"group behavior:"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause ending at the blank ("arguing that...coordinating group behavior") is a complete sentence. The clause beginning with "subsequent laboratory experiments" is also an independent clause. A period correctly separates these two independent sentences. The option "group behavior; however, subsequent" incorrectly inserts the conjunctive adverb "however," which signals contrast, but the second clause confirms rather than contradicts the first. The option "group behavior," creates a comma splice between two independent clauses. The option "group behavior:" incorrectly implies that what follows is a list, elaboration, or restatement of "group behavior," when the second clause introduces new information about laboratory experiments.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KVBDFM', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Marine biologist Priya Deshpande found that elevated water temperatures in the Gulf of Mannar triggered mass bleaching in Acropora coral colonies during 2019. Her team also documented that the few colonies that survived the bleaching event harbored unusually dense populations of thermotolerant Durusdinium symbionts. __________ when Deshpande''s team transplanted fragments from these surviving colonies to a degraded reef section in 2022, the fragments not only persisted through a subsequent thermal spike but also facilitated recolonization by native coral larvae in adjacent plots.', E'Marine biologist Priya Deshpande found that elevated water temperatures in the Gulf of Mannar triggered mass bleaching in Acropora coral colonies during 2019. Her team also documented that the few colonies that survived the bleaching event harbored unusually dense populations of thermotolerant Durusdinium symbionts. __________ when Deshpande''s team transplanted fragments from these surviving colonies to a degraded reef section in 2022, the fragments not only persisted through a subsequent thermal spike but also facilitated recolonization by native coral larvae in adjacent plots.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"Building on this finding,"},{"key":"D","text":"In sum,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage traces a causal sequence: the team discovered that surviving colonies harbored thermotolerant symbionts, and then used that discovery as the basis for a transplantation experiment. The third sentence describes a next step that follows from and extends the prior finding. "Building on this finding" correctly captures the sequential, cause-to-effect relationship between the observation and the subsequent experiment. "Similarly" incorrectly implies the transplant experiment is a parallel case to the bleaching observation, but it is a consequent action derived from it, not an analogous situation. "Nevertheless" incorrectly introduces a concession, suggesting the transplant result contradicts the earlier observation, when in fact it confirms and extends it. "In sum" incorrectly suggests the final sentence is summarizing the preceding information, when it actually introduces new experimental results not previously mentioned.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LGKWPJ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which quotation from a research publication would, if accurate, most effectively undermine the conclusion drawn by Haddad''s team?', E'Glaciologist Rania Haddad and her team analyzed oxygen isotope ratios in ice cores extracted from the Quelccaya ice cap in Peru, spanning the period from 1450 to 1820 CE. They concluded that the Little Ice Age in tropical South America was characterized by consistently cooler and wetter conditions than the preceding Medieval Warm Period. Haddad''s team specifically argued that the isotopic signal rules out the possibility that the Little Ice Age climate in this region was marked by significant multi-decadal dry intervals, a finding they described as inconsistent with drought-driven collapse theories for late pre-Columbian Andean societies.', $lyceon_json$[{"key":"A","text":"\"Our analysis of lake sediment cores from three sites within 200 kilometers of Quelccaya reveals pronounced dry intervals lasting 30 to 70 years during the 1500–1750 CE period, with isotopic and pollen signatures that diverge sharply from the uniformly wet conditions reported in Quelccaya ice core studies.\""},{"key":"B","text":"\"Oxygen isotope records from Greenland ice cores confirm that the Northern Hemisphere experienced sustained cooling during the Little Ice Age, consistent with reduced solar irradiance and increased volcanic aerosol loading.\""},{"key":"C","text":"\"Archaeological evidence from coastal Peru indicates that several late pre-Columbian settlements were abandoned during the fifteenth century, though the precise climatic drivers of these abandonments remain debated.\""},{"key":"D","text":"\"Our re-calibration of the Quelccaya ice core chronology shifts several key isotopic excursions by approximately 15 years, though the overall pattern of cooler, wetter conditions during the Little Ice Age remains unchanged.\""}]$lyceon_json$::jsonb, 'A', NULL, E'Haddad''s conclusion is that the Little Ice Age in tropical South America was consistently cooler and wetter, with no significant multi-decadal dry intervals. The quotation about lake sediment cores near Quelccaya revealing pronounced dry intervals of 30 to 70 years directly contradicts this conclusion by providing independent proxy evidence of extended droughts in the same region and time period. The quotation about Greenland ice cores addresses the Northern Hemisphere and general cooling mechanisms, which does not undermine a claim about tropical South American precipitation patterns. The quotation about archaeological abandonments mentions climatic drivers as debated, offering no definitive evidence against Haddad''s specific isotopic findings. The quotation about re-calibration of the Quelccaya chronology explicitly states that the overall pattern of cooler, wetter conditions remains unchanged, so it actually supports rather than undermines Haddad''s conclusion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MIH7KU', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'_______ over 400 handwritten letters archived in the Estonian Literary Museum, the historian Piret Kallas reconstructed a previously unknown correspondence network linking nineteenth-century Baltic poets to radical political movements in St. Petersburg.', $lyceon_json$[{"key":"A","text":"Analyzing"},{"key":"B","text":"Having been analyzed"},{"key":"C","text":"To have analyzed"},{"key":"D","text":"Being analyzed"}]$lyceon_json$::jsonb, 'A', NULL, E'The introductory participial phrase must have as its logical subject the noun immediately following the comma—in this case, "the historian Piret Kallas." Kallas is the person performing the analysis, so the active present participle "Analyzing" correctly modifies her: she analyzed the letters and thereby reconstructed the network. "Having been analyzed" is a passive construction that would make Kallas the one being analyzed, which is illogical—it is the letters, not the historian, that were analyzed. "To have analyzed" is an infinitive perfect form that does not function as a participial modifier; it lacks the grammatical structure needed to introduce an adverbial modifying phrase for the main clause. "Being analyzed" is a passive progressive participle that would again cast the subject as the entity being analyzed and would also illogically suggest the analysis was ongoing and performed by someone else while Kallas reconstructed the network.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MV8ZBU', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "embraced" most nearly mean?', E'When the city council announced new bike lane projects in 2019, several neighborhood associations initially resisted, citing traffic concerns. By 2022, however, the majority of residents had embraced the cycling infrastructure, noting reduced commute times and improved air quality along the redesigned corridors.', $lyceon_json$[{"key":"A","text":"hugged"},{"key":"B","text":"adopted"},{"key":"C","text":"confronted"},{"key":"D","text":"monitored"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes residents who initially resisted cycling infrastructure but later came to accept and support it. "Adopted" means to take up or accept something willingly, which fits the shift from resistance to approval. "Hugged" refers to the physical act of wrapping one''s arms around something and produces an incoherent meaning when substituted. "Confronted" means to face something in opposition, which contradicts the passage''s description of a positive shift. "Monitored" means to observe or track, which does not convey the acceptance described in the passage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NS42J0', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a topic, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PGDWY6', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A team of entomologists studying pollinator decline in the Scottish Highlands discovered that certain wild bee populations have shifted their foraging schedules by nearly three weeks over the past _______ the researchers attribute this temporal drift to rising spring temperatures, which cause early-blooming wildflowers to produce nectar before the bees'' traditional emergence dates.', $lyceon_json$[{"key":"A","text":"decade, the"},{"key":"B","text":"decade. The"},{"key":"C","text":"decade; however, the"},{"key":"D","text":"decade—the"}]$lyceon_json$::jsonb, 'B', NULL, E'The blank falls between two independent clauses: the first reports a discovery about shifted foraging schedules, and the second explains the cause. A period correctly separates these two complete sentences. The comma option creates a comma splice by joining two independent clauses with only a comma and no coordinating conjunction. The option using a semicolon with "however" distorts the logical relationship between the clauses—"however" signals contrast or concession, but the second clause provides a causal explanation for the first, not a contrasting point. The dash option incorrectly treats the second clause as an abrupt aside or dramatic amplification; in Standard English, a dash before a full independent clause that introduces a new causal explanation (with its own embedded relative clause) is not a conventional boundary.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QBUK78', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit of the New Zealand kauri tree (Agathis australis) can take over eighteen months to mature after pollination, one of the longest seed development periods of any conifer. During this extended maturation, the developing cones remain tightly sealed and firmly attached to the parent tree, unlike the cones of many pine species, which open and release seeds within a single growing season. Botanists believe this prolonged development reflects an adaptation to ________', $lyceon_json$[{"key":"A","text":"New Zealand's mild, stable climate, which provides a reliably long growing window that makes an extended maturation period viable."},{"key":"B","text":"the exceptionally large size of mature kauri trees, which require proportionally larger cones to produce viable seeds."},{"key":"C","text":"the volcanic soils found throughout New Zealand, which supply the mineral-rich nutrients necessary for slow embryonic development."},{"key":"D","text":"competition with flowering plants, which forced conifers to develop longer pollination cycles to attract different insect species."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage emphasizes the kauri''s unusually long seed maturation period and contrasts it with pine species that release seeds within a single growing season. The most logical inference is that this prolonged development is viable because New Zealand''s mild, stable climate provides a long enough growing window for such a strategy to succeed. The option about tree size requiring larger cones introduces a causal link between tree size and cone size that the passage does not support and that does not logically follow from the information given. The option about volcanic soils supplying nutrients introduces an entirely unsupported mechanism—the passage mentions no soil conditions. The option about competition with flowering plants introduces insect pollination, which is irrelevant since kauri cones are wind-pollinated and the passage says nothing about pollinator competition.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RO5O60', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Historian Elif Arslan has documented that Ottoman-era caravanserais—roadside inns built to shelter traveling merchants—were spaced at remarkably consistent intervals of roughly 30 to 40 kilometers along major trade routes. Arslan notes that this spacing corresponds closely to the maximum distance a loaded camel caravan could cover in a single day''s march. While some scholars have attributed the regularity to centralized imperial planning, Arslan contends that the pattern more likely emerged from ________', $lyceon_json$[{"key":"A","text":"the practical constraints of animal-powered transport, which made caravanserais commercially viable only if they were reachable within one day's travel from the previous stop."},{"key":"B","text":"the Ottoman government's desire to collect standardized tariffs at evenly distributed checkpoints along trade routes."},{"key":"C","text":"a religious requirement that travelers perform daily prayers at designated waypoints administered by state-appointed clerics."},{"key":"D","text":"the influence of earlier Roman road-station spacing, which Ottoman builders replicated without modification when constructing new trade infrastructure."}]$lyceon_json$::jsonb, 'A', NULL, E'Arslan explicitly contrasts her view with the centralized planning explanation, arguing for an alternative cause. The passage links the spacing to the maximum daily distance of a loaded camel caravan, and Arslan contends the pattern emerged from something other than imperial planning. The option about practical transport constraints logically completes the argument: caravanserais were viable because they matched the natural stopping points dictated by camel travel limits. The option about standardized tariffs at checkpoints aligns with the centralized planning view that Arslan is arguing against, not with her own contention. The option about religious requirements at waypoints introduces a claim entirely absent from the passage. The option about replicating Roman road-station spacing introduces a historical precedent the passage never mentions and contradicts Arslan''s framing, which focuses on organic emergence rather than deliberate replication.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RROXIV', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the original hypothesis proposed by the climatologist Dr. Ingrid Svensson nor the revised model developed independently by a team at the University of _______ able to account for the anomalous temperature readings recorded at three Arctic monitoring stations during the winter of 2021.', $lyceon_json$[{"key":"A","text":"Tromsø were"},{"key":"B","text":"Tromsø are"},{"key":"C","text":"Tromsø was"},{"key":"D","text":"Tromsø have been"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence uses the correlative conjunction "neither...nor," which requires the verb to agree in number with the nearer subject. The nearer subject is "the revised model," which is singular, so the verb must be singular. Additionally, the sentence describes events in the past (the winter of 2021), requiring past tense. "Was" is both singular and past tense, correctly matching the nearer subject and the temporal context. "Were" is plural past tense, which would be correct if the nearer subject were plural, but "model" is singular. "Are" is plural present tense, failing on both number agreement and tense. "Have been" is plural present perfect, also failing on both number (plural instead of singular) and tense (present perfect instead of simple past, which is inappropriate given the specific past time reference "the winter of 2021").', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RW4BQ6', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Historian Tomoko Harada has argued that the 1923 Great Kanto earthquake accelerated the adoption of reinforced-concrete construction in Tokyo not primarily through building codes—which remained largely advisory until 1950—but through insurance incentives that made wooden structures prohibitively expensive to insure. __________ the proliferation of concrete buildings in Osaka during the same period, where no comparable insurance restructuring occurred, proceeded at nearly the same pace, driven instead by municipal zoning ordinances enacted after a series of urban fires in 1921.', E'Historian Tomoko Harada has argued that the 1923 Great Kanto earthquake accelerated the adoption of reinforced-concrete construction in Tokyo not primarily through building codes—which remained largely advisory until 1950—but through insurance incentives that made wooden structures prohibitively expensive to insure. __________ the proliferation of concrete buildings in Osaka during the same period, where no comparable insurance restructuring occurred, proceeded at nearly the same pace, driven instead by municipal zoning ordinances enacted after a series of urban fires in 1921.', $lyceon_json$[{"key":"A","text":"That is,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"Moreover,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage juxtaposes Tokyo, where insurance incentives drove concrete adoption, with Osaka, where different mechanisms (municipal zoning after fires) produced a similar outcome without those insurance incentives. The second sentence highlights a contrasting case with a different causal pathway. "By contrast" correctly signals that Osaka''s experience is being set against Tokyo''s to show a different driving force behind the same trend. "That is" incorrectly suggests the second sentence restates or clarifies the first, when it actually introduces a separate city with a distinct causal mechanism. "Moreover" incorrectly implies the Osaka case is additional supporting evidence for Harada''s insurance argument, when it actually presents a counterexample showing a different cause. "Consequently" incorrectly implies that the Osaka development resulted from the Tokyo insurance restructuring, when the passage explicitly states no comparable insurance restructuring occurred in Osaka.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
