INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UC8SF1', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The architect Lúcia Ferreira, who designed the award-winning Pavilion of Echoes in Porto, has argued that buildings should be conceived not as static enclosures but as instruments that shape _______ her latest project, a concert hall in Braga whose walls are lined with thousands of ceramic tiles angled at mathematically precise intervals, translates this philosophy into a structure that redistributes sound waves so that every seat receives nearly identical acoustic quality.', $lyceon_json$[{"key":"A","text":"sound. Her"},{"key":"B","text":"sound, her"},{"key":"C","text":"sound; however, her"},{"key":"D","text":"sound—her"}]$lyceon_json$::jsonb, 'A', NULL, E'The blank falls between two independent clauses: "buildings should be conceived not as static enclosures but as instruments that shape sound" and "her latest project...translates this philosophy into a structure..." A period followed by a capital letter correctly separates these independent clauses. The option "sound, her" creates a comma splice between two independent clauses. The option "sound; however, her" is grammatically well-formed but logically incorrect: the conjunctive adverb "however" signals contrast or concession, but the second clause exemplifies and confirms the first clause''s argument rather than contrasting with it. The latest project translates Ferreira''s philosophy into practice, which is continuation, not contradiction. The option "sound\\u2014her" uses an em dash, which would signal an interruption or parenthetical aside, misrepresenting the relationship between the two clauses; the second clause is a separate, complete statement about a specific project, not a parenthetical elaboration of "sound."', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W9TTNV', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the overall purpose of the text?', E'Critics have praised novelist Seo Min-ji for rendering rural Jeolla Province in prose so meticulous that readers can almost smell the barley fields after rain. Yet this very meticulousness, paradoxically, drains Seo''s characters of interiority: they become fixtures of landscape rather than agents of narrative. The dialect dialogue that reviewers celebrate as "authentic" often reads less like speech and more like ethnographic notation, cataloging regional idiom at the expense of dramatic momentum. Admiration for Seo''s descriptive power is warranted, but it should not obscure the cost her method exacts on storytelling.', $lyceon_json$[{"key":"A","text":"It argues that a novelist's acclaimed stylistic strength simultaneously creates significant narrative weaknesses."},{"key":"B","text":"It compares two novelists' approaches to regional fiction and identifies which approach produces more compelling characters."},{"key":"C","text":"It summarizes the critical consensus on a novelist's work and endorses that consensus without qualification."},{"key":"D","text":"It traces the evolution of a novelist's style across multiple works, noting how her technique has changed over time."}]$lyceon_json$::jsonb, 'A', NULL, E'The text acknowledges critics'' praise for Seo''s descriptive meticulousness but argues that this same strength weakens her characters and narrative momentum, concluding that admiration should not obscure the cost. The overall purpose is to show how an acclaimed strength simultaneously creates weaknesses. The option about comparing two novelists is wrong because the passage discusses only Seo Min-ji. The option about endorsing critical consensus without qualification is wrong because the passage explicitly qualifies and complicates the consensus, identifying costs that praise overlooks. The option about tracing stylistic evolution is wrong because the passage does not discuss changes in Seo''s technique over time—it analyzes a single consistent method.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y1U81W', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the function of the second sentence in the overall structure of the text?', E'Archaeological surveys of the Faroe Islands long assumed that Norse settlers arrived around 800 CE, finding the islands uninhabited. However, a 2021 analysis of lake sediment cores from Eiði revealed cereal pollen and charcoal deposits dating to approximately 500 CE, suggesting that an earlier, unidentified population had already been cultivating crops and clearing land three centuries before the Norse migration.', $lyceon_json$[{"key":"A","text":"It presents evidence that challenges the assumption introduced in the first sentence."},{"key":"B","text":"It provides an example that confirms the claim made in the first sentence."},{"key":"C","text":"It describes the methodology archaeologists used to verify the Norse arrival date."},{"key":"D","text":"It explains why scholars originally placed Norse settlement at 800 CE."}]$lyceon_json$::jsonb, 'A', NULL, E'The first sentence states the long-held assumption that Norse settlers arrived around 800 CE to uninhabited islands. The second sentence, introduced by "However," presents sediment evidence of an earlier population around 500 CE, directly contradicting that assumption. The option claiming the evidence confirms the first sentence is wrong because the word "However" and the 500 CE dating explicitly challenge the 800 CE assumption. The option about methodology is wrong because the second sentence focuses on what the evidence revealed, not on how the analysis was conducted. The option about explaining why scholars placed settlement at 800 CE is wrong because the second sentence does not provide reasoning for the original assumption—it undercuts it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z2JQUN', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Marine biologists studying the Galápagos penguin have documented an unusual behavioral adaptation: unlike most penguin species, which breed on a fixed annual schedule, Galápagos penguins breed opportunistically, timing their reproduction to coincide with periods when ocean surface temperatures drop below 24 degrees Celsius. These cooler conditions trigger upwellings of nutrient-rich water, which in turn support the dense schools of small fish on which the penguins depend. By coupling their breeding cycle to oceanographic conditions rather than to seasonal cues, Galápagos penguins maximize the likelihood that chicks will hatch during periods of abundant food.', $lyceon_json$[{"key":"A","text":"Galápagos penguins have evolved a flexible breeding strategy linked to ocean temperature changes that ensure food availability for their offspring."},{"key":"B","text":"Galápagos penguins are the only penguin species that do not follow a fixed annual breeding schedule."},{"key":"C","text":"Ocean upwellings near the Galápagos Islands are primarily caused by drops in surface temperature below 24 degrees Celsius."},{"key":"D","text":"Marine biologists have recently discovered that Galápagos penguins feed exclusively on small schooling fish."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on the Galápagos penguin''s adaptation of breeding in response to ocean temperature rather than seasonal cues, ensuring food is plentiful for chicks. The option stating that these penguins evolved a flexible breeding strategy linked to ocean temperature changes captures this central idea. The option claiming they are the only species without a fixed schedule distorts the text, which says ''unlike most'' species, not all. The option about upwellings being caused by temperature drops focuses on a supporting detail rather than the main idea. The option about feeding exclusively on small schooling fish misreads the passage, which describes dense schools of small fish as a food source but does not claim exclusivity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z8GHNV', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching a topic, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZXCEMV', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Neuroscientist Clara Reinholt''s research on decision fatigue has revealed a counterintuitive pattern: experienced judges issuing parole decisions do not simply become more lenient or more severe as the day progresses. Instead, Reinholt found that judges'' rulings after prolonged decision-making sessions increasingly default to whichever outcome requires less justification within the institutional context. In courts where parole denial is the default position requiring minimal written explanation, fatigued judges denied parole at higher rates; conversely, in jurisdictions where granting parole is procedurally simpler, fatigued judges granted parole more frequently. Reinholt argues that this pattern implies that decision fatigue does not impair judgment in a single predictable direction but rather ________', $lyceon_json$[{"key":"A","text":"amplifies the influence of institutional defaults by reducing the cognitive resources available to override procedurally entrenched options."},{"key":"B","text":"causes judges to rely more heavily on the specific details of each case rather than on general sentencing guidelines."},{"key":"C","text":"primarily affects inexperienced judges who have not yet developed the procedural habits necessary to resist default options."},{"key":"D","text":"has been overstated in prior research because experienced professionals develop effective strategies for maintaining consistent decision quality throughout the day."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that fatigued judges default to whichever outcome requires less justification in their institutional context, and that the direction of the bias depends on which option is procedurally simpler. The logical completion is that fatigue amplifies institutional defaults by depleting the cognitive resources needed to override them. The option about relying more heavily on case-specific details contradicts the passage''s finding—fatigue leads to defaulting rather than to deeper engagement with individual cases. The option about inexperienced judges contradicts the passage, which explicitly states the research studied experienced judges. The option about decision fatigue being overstated contradicts the passage''s premise: Reinholt''s research confirms that fatigue systematically affects rulings, just not in a single predictable direction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
